"""组件定义数据库

每个组件包含：
- render(params) -> SVG字符串（渲染在原点(0,0)）
- ports: 连接端口（相对原点偏移dx/dy）
- default_w/h: 默认尺寸
- z: 默认深度（越大越靠前）
- name/category: 元数据
"""

import math
import html

from .liquid_render import LIQUID_PRESETS

# ──────────── 渲染辅助函数 ────────────

def _safe_num(val, default: float = 0.0) -> float:
    """安全数值转换：保留合法的 0 / 负数，非法或非有限值回退 default。"""
    if val is None or val == "":
        return default
    try:
        v = float(val)
        return v if math.isfinite(v) else default
    except (TypeError, ValueError):
        return default


def _color(name: str) -> str:
    """常用颜色常量"""
    palette = {
        "glass": "rgba(200,220,240,0.15)",   # 玻璃半透明
        "water": "rgba(70,150,220,0.18)",    # 水
        "flame_o": "#ff8c00", "flame_y": "#ffd700",  # 火焰
        "iron": "#888",                       # 铁架台
        "rubber": "#555",                     # 橡胶
        "wood": "#c8a96e",                    # 木塞/木制品
        "wire": "#999",                       # 金属网
    }
    return palette.get(name, name)


def _liquid_fill(p: dict) -> str:
    """根据 liquid_color 参数返回容器内液体填充色。

    - water / 缺省 / 未知：返回 _color("water")，保持原有水蓝色视觉；
    - 其他预设（acid/base/oil/indicator）：返回 LIQUID_PRESETS 对应的 rgba(color,opacity)。
    """
    key = p.get("liquid_color", "water")
    if key == "water" or key == "default":
        return _color("water")
    preset = LIQUID_PRESETS.get(key)
    if not preset:
        return _color("water")
    hexc = str(preset["color"]).lstrip("#")
    if len(hexc) != 6:
        return _color("water")
    r = int(hexc[0:2], 16); g = int(hexc[2:4], 16); b = int(hexc[4:6], 16)
    return f"rgba({r},{g},{b},{preset['opacity']})"


# ──────────── 容器类 ────────────

def _beaker_svg(p: dict) -> str:
    """烧杯 - 梯形+液体"""
    w = p.get("w", 50)
    h = p.get("h", 42)
    lq = p.get("liquid", 0.5)
    label = p.get("label", "")
    tw = w * 0.8
    off = (w - tw) / 2
    parts = [
        f'<polygon points="0,0 {w},0 {off+tw},{h} {off},{h}" fill="none" stroke="#333" stroke-width="1.5"/>',
        f'<line x1="0" y1="0" x2="{w}" y2="0" stroke="#333" stroke-width="1.5"/>',
        f'<line x1="2" y1="-3" x2="2" y2="0" stroke="#333" stroke-width="1"/>',
        f'<line x1="{w-2}" y1="-3" x2="{w-2}" y2="0" stroke="#333" stroke-width="1"/>',
    ]
    if lq > 0:
        ly = h - (h - 4) * lq
        parts.append(
            f'<rect x="{off+2}" y="{ly}" width="{tw-4}" height="{(h-4)*lq}" fill="{_liquid_fill(p)}" stroke="none"/>'
        )
    if label:
        parts.append(
            f'<text x="{w/2}" y="{h+14}" font-size="11" fill="#333" text-anchor="middle">{label}</text>'
        )
    return "\n".join(parts)


