def _round_bottom_flask_svg(p: dict) -> str:
    """圆底烧瓶 - 真实SVG"""
    w = p.get("w", 48)
    h = p.get("h", 73)
    label = p.get("label", "")
    VW, VH = 35, 52  # original viewBox aspect
    inner = (
        f'<svg viewBox="0 0 {VW} {VH}" width="{w}" height="{h}">'
        '<defs><linearGradient id="rbf_b" x1="50%" y1="0%" x2="50%" y2="100%">'
        '<stop offset="0" stop-color="#989898"/><stop offset="1" stop-color="#dedede"/></linearGradient></defs>'
        # flask body - round bottom with neck
        '<rect x="13.6" y="10" width="7.8" height="19" fill="none" stroke="#000" stroke-width="0.6" rx="1"/>'
        '<path d="M13.6,29 Q13.6,46 17.5,46 Q21.4,46 21.4,29" fill="none" stroke="#000" stroke-width="0.6"/>'
        # liquid fill
        '<path d="M14,32 Q14,44 17.5,44 Q21,44 21,32 Z" fill="#c2e5ef" opacity="0.77"/>'
        # neck opening
        '<rect x="11.6" y="9" width="11.8" height="2" rx="1" fill="url(#rbf_b)" stroke="#000" stroke-width="0.4"/>'
        '</svg>'
    )
    parts = [inner]
    if label:
        parts.append(f'<text x="{w/2}" y="{h+14}" font-size="11" fill="#333" text-anchor="middle">{label}</text>')
    return "\n".join(parts)


def _flat_bottom_flask_svg(p: dict) -> str:
    """平底烧瓶 - 瓶颈+宽平底瓶身"""
    w = p.get("w", 48)
    h = p.get("h", 55)
    lq = p.get("liquid", 0.25)
    label = p.get("label", "")
    neck_w = w * 0.24
    no = (w - neck_w) / 2
    body_w = w * 0.85
    bo = (w - body_w) / 2
    body_h = h * 0.6
    parts = [
        f'<rect x="{no}" y="0" width="{neck_w}" height="{h-body_h}" fill="none" stroke="#333" stroke-width="1.5"/>',
        f'<line x1="{no-2}" y1="0" x2="{no-2}" y2="-4" stroke="#333" stroke-width="1.5"/>',
        f'<line x1="{w-no+2}" y1="0" x2="{w-no+2}" y2="-4" stroke="#333" stroke-width="1.5"/>',
        f'<path d="M{no},{h-body_h} Q{no},{h-body_h+5} {bo},{h-body_h+5} L{bo},{h} L{w-bo},{h} L{w-bo},{h-body_h+5} Q{w-no},{h-body_h+5} {w-no},{h-body_h}" fill="none" stroke="#333" stroke-width="1.5"/>',
    ]
    if lq > 0:
        lh = body_h * lq
        ly = h - lh
        parts.append(
            f'<rect x="{bo+1}" y="{ly}" width="{body_w-2}" height="{lh-1}" fill="{_liquid_fill(p)}" stroke="none"/>'
        )
    if label:
        parts.append(
            f'<text x="{w/2}" y="{h+14}" font-size="11" fill="#333" text-anchor="middle">{label}</text>'
        )
    return "\n".join(parts)


