# ──────────── 加热类 ────────────

def _alcohol_lamp_svg(p: dict) -> str:
    """酒精灯 - 梯形主体+灯芯+火焰"""
    w = p.get("w", 32)
    h = p.get("h", 40)
    label = p.get("label", "")
    bw = w * 0.7
    bo = (w - bw) / 2
    neck_w = w * 0.25
    no = (w - neck_w) / 2
    parts = [
        f'<polygon points="{bo},{h} {w-bo},{h} {w},{h*0.4} {0},{h*0.4}" fill="none" stroke="#333" stroke-width="1.5"/>',
        f'<rect x="{no}" y="{h*0.2}" width="{neck_w}" height="{h*0.2}" fill="none" stroke="#333" stroke-width="1.5"/>',
        f'<line x1="{w/2}" y1="{h*0.2}" x2="{w/2}" y2="{h*0.08}" stroke="#333" stroke-width="1.5"/>',
    ]
    # 火焰
    fx, fy = w / 2, h * 0.08
    fh = h * 0.12
    parts.extend([
        f'<path d="M{fx},{fy-fh} Q{fx+fh*0.3},{fy} {fx},{fy+fh*0.1} Q{fx-fh*0.3},{fy} {fx},{fy-fh}" fill="{_color("flame_o")}" stroke="#333" stroke-width="0.5"/>',
        f'<path d="M{fx},{fy-fh*0.6} Q{fx+fh*0.15},{fy-fh*0.2} {fx},{fy} Q{fx-fh*0.15},{fy-fh*0.2} {fx},{fy-fh*0.6}" fill="{_color("flame_y")}" stroke="none"/>',
    ])
    if label:
        parts.append(
            f'<text x="{w/2}" y="{h+14}" font-size="11" fill="#333" text-anchor="middle">{label}</text>'
        )
    return "\n".join(parts)


def _tripod_svg(p: dict) -> str:
    """三脚架 - 顶环+三条腿"""
    w = p.get("w", 50)
    h = p.get("h", 40)
    label = p.get("label", "")
    cx, cy = w / 2, h * 0.25
    r = w * 0.4
    parts = [
        f'<ellipse cx="{cx}" cy="{cy}" rx="{r}" ry="{r*0.3}" fill="none" stroke="#333" stroke-width="2"/>',
        f'<line x1="{cx-r}" y1="{cy}" x2="{cx-r*0.7}" y2="{h}" stroke="#333" stroke-width="2"/>',
        f'<line x1="{cx+r}" y1="{cy}" x2="{cx+r*0.7}" y2="{h}" stroke="#333" stroke-width="2"/>',
        f'<line x1="{cx}" y1="{cy+r*0.3}" x2="{cx}" y2="{h}" stroke="#333" stroke-width="2"/>',
    ]
    if label:
        parts.append(
            f'<text x="{cx}" y="{h+14}" font-size="11" fill="#333" text-anchor="middle">{label}</text>'
        )
    return "\n".join(parts)


def _wire_gauze_svg(p: dict) -> str:
    """石棉网 - 网格"""
    w = p.get("w", 46)
    h = p.get("h", 10)
    label = p.get("label", "")
    parts = [f'<rect x="0" y="0" width="{w}" height="{h}" fill="none" stroke="#999" stroke-width="1"/>']
    for i in range(5):
        x = (i + 1) * w / 6
        parts.append(f'<line x1="{x}" y1="0" x2="{x}" y2="{h}" stroke="#ccc" stroke-width="0.5"/>')
    for i in range(2):
        y = (i + 1) * h / 3
        parts.append(f'<line x1="0" y1="{y}" x2="{w}" y2="{y}" stroke="#ccc" stroke-width="0.5"/>')
    if label:
        parts.append(
            f'<text x="{w/2}" y="{h+14}" font-size="11" fill="#333" text-anchor="middle">{label}</text>'
        )
    return "\n".join(parts)


def _crucible_svg(p: dict) -> str:
    """坩埚 - 小碗+盖"""
    w = p.get("w", 24)
    h = p.get("h", 18)
    label = p.get("label", "")
    parts = [
        f'<path d="M2,{h} L{w-2},{h} Q{w},{h*0.6} {w},{h*0.3} L{0},{h*0.3} Q{0},{h*0.6} 2,{h}" fill="none" stroke="#333" stroke-width="1.5"/>',
        f'<ellipse cx="{w/2}" cy="{h*0.3}" rx="{w/2-1}" ry="3" fill="none" stroke="#333" stroke-width="1"/>',
    ]
    if label:
        parts.append(
            f'<text x="{w/2}" y="{h+14}" font-size="11" fill="#333" text-anchor="middle">{label}</text>'
        )
    return "\n".join(parts)


