def _funnel_svg(p: dict) -> str:
    """漏斗+滤纸 - Servier/OpenClipart SVG"""
    w = p.get("w", 40)
    h = p.get("h", 76)
    label = p.get("label", "")
    VW, VH = 204.132, 385.625
