def _separatory_funnel_svg(p: dict) -> str:
    """分液漏斗 - 球体+上下管+活塞"""
    w = p.get("w", 32)
    h = p.get("h", 54)
    label = p.get("label", "")
    cx, cy = w / 2, h * 0.4
    r = w * 0.42
    nw = w * 0.2
    no = (w - nw) / 2
    parts = [
        f'<rect x="{no}" y="0" width="{nw}" height="{h*0.18}" fill="none" stroke="#333" stroke-width="1.5"/>',
        f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="#333" stroke-width="1.5"/>',
        f'<rect x="{no}" y="{cy+r*1.1}" width="{nw}" height="{h-cy-r*1.1}" fill="none" stroke="#333" stroke-width="1.5"/>',
        f'<rect x="{no-2}" y="{cy+r*1.1+3}" width="{nw+4}" height="3" fill="{_color("iron")}" stroke="#333" stroke-width="0.5"/>',
    ]
    if label:
        parts.append(
            f'<text x="{cx}" y="{h+14}" font-size="11" fill="#333" text-anchor="middle">{label}</text>'
        )
    return "\n".join(parts)


