def _distillation_head_svg(p: dict) -> str:
    """蒸馏头 - Y型三通（侧管向右连接冷凝管）"""
    w = p.get("w", 30)
    h = p.get("h", 30)
    label = p.get("label", "")
    nw = w * 0.25
    no = (w - nw) / 2
    cx = w / 2
    parts = [
        # 下管（连接烧瓶）
        f'<rect x="{no}" y="0" width="{nw}" height="{h*0.4}" fill="none" stroke="#333" stroke-width="1.5"/>',
        # 上管（温度计口）
        f'<rect x="{no}" y="{h*0.4}" width="{nw}" height="{h*0.3}" fill="none" stroke="#333" stroke-width="1.5"/>',
        # 侧管（连接冷凝管，向右伸出）
        f'<path d="M{w-no},{h*0.55} L{w-no+8},{h*0.7} L{w-no+8},{h*0.85}" fill="none" stroke="#333" stroke-width="1.5"/>',
        # 管口
        f'<line x1="{w-no+8}" y1="{h*0.85}" x2="{w-no+8}" y2="{h}" stroke="#333" stroke-width="1.5"/>',
        f'<line x1="{no-2}" y1="0" x2="{no-2}" y2="-3" stroke="#333" stroke-width="1.5"/>',
        f'<line x1="{w-no+2}" y1="0" x2="{w-no+2}" y2="-3" stroke="#333" stroke-width="1.5"/>',
    ]
    if label:
        parts.append(
            f'<text x="{cx}" y="{h+14}" font-size="11" fill="#333" text-anchor="middle">{label}</text>'
        )
    return "\n".join(parts)


def _cow_receiver_svg(p: dict) -> str:
    """牛角管（接液管）- 弯管"""
    w = p.get("w", 20)
    h = p.get("h", 30)
