def _thermometer_svg(p: dict) -> str:
    """温度计 - 细管+球泡+刻度+示数

    参数：
        temperature: 温度值（默认 25，范围 -20~200），线性映射为红色液柱高度
        show_scale: 是否显示刻度
    """
    w = _safe_num(p.get("w"), 8)
    h = _safe_num(p.get("h"), 50)
    label = str(p.get("label", "") or "")
    show_scale = p.get("show_scale", True)
    temperature = _safe_num(p.get("temperature", 25), 25)
    # 温度范围线性映射：-20 → 0%（仅球泡红），200 → 100%（液柱满管）
    T_MIN, T_MAX = -20.0, 200.0
    pct = (temperature - T_MIN) / (T_MAX - T_MIN)
    pct = max(0.0, min(1.0, pct))
    bulb_r = w * 0.45
    tube_h = h - bulb_r * 2 - 8  # 留出更多顶部空间
    tube_top = 8
    tube_bottom = tube_top + tube_h
    parts = [
        f'<rect x="0" y="{tube_top}" width="{w}" height="{tube_h}" rx="{w/2}" fill="none" stroke="#333" stroke-width="1.5"/>',
        f'<circle cx="{w/2}" cy="{tube_bottom+bulb_r}" r="{bulb_r}" fill="none" stroke="#333" stroke-width="1.5"/>',
        f'<circle cx="{w/2}" cy="{tube_bottom+bulb_r}" r="{bulb_r-1}" fill="#e33" stroke="none"/>',
    ]
    # 红色液柱：从球泡上方管底向上升到 pct 高度
    if tube_h > 0 and pct > 0:
        liquid_h = tube_h * pct
        ly = tube_bottom - liquid_h
        # 液柱宽度为管宽的 60%，居中
        lx = w * 0.2
        lw = w * 0.6
        parts.append(
            f'<rect x="{lx}" y="{ly}" width="{lw}" height="{liquid_h}" fill="#e33" stroke="none"/>'
        )
    # 刻度线+示数（按 -20~200 范围标注：顶部高温，底部低温）
    if show_scale and tube_h > 20:
        num_ticks = 5
        tick_spacing = tube_h / num_ticks
        for i in range(num_ticks + 1):
            ty = tube_top + i * tick_spacing
            is_major = i % 2 == 0
            tick_len = 6 if is_major else 4
            parts.append(
                f'<line x1="{w}" y1="{ty}" x2="{w+tick_len}" y2="{ty}" stroke="#666" stroke-width="{1.5 if is_major else 1.0}"/>'
            )
            if is_major:
                # i=0 在顶部（高温 200），i=num_ticks 在底部（低温 -20）
                val = int(T_MAX - i * (T_MAX - T_MIN) / num_ticks)
                parts.append(
                    f'<text x="{w+tick_len+4}" y="{ty+5}" font-size="9" fill="#666">{val}</text>'
                )
    # 标签：拼接温度数值（如 "温度计 25°C"，无标签时仅 "25°C"）
    temp_str = f"{int(round(temperature))}°C"
    if label:
        display_text = f"{label} {temp_str}"
    else:
        display_text = temp_str
    parts.append(
        f'<text x="{w/2}" y="{h+12}" font-size="11" fill="#333" text-anchor="middle">{display_text}</text>'
    )
    return "\n".join(parts)


def _measure_display_svg(p: dict) -> str:
    """通用展示仪器：量筒、弹簧测力计、刻度尺、温度计。

    参数：measure_type、min、max、value、position、direction、label。
    direction=horizontal 时复用同一套刻度逻辑旋转 90 度，避免两套坐标算法漂移。
    """
    w = max(20.0, _safe_num(p.get("w"), 58.0))
    h = max(30.0, _safe_num(p.get("h"), 120.0))
    kind = str(p.get("measure_type", "graduated_cylinder")).strip().lower()
    kind = {
        "cylinder": "graduated_cylinder", "量筒": "graduated_cylinder",
        "spring": "spring_scale", "spring_balance": "spring_scale", "弹簧测力计": "spring_scale",
        "ruler": "ruler", "刻度尺": "ruler",
        "thermometer": "thermometer", "温度计": "thermometer",
    }.get(kind, kind)
    direction = str(p.get("direction", "vertical")).strip().lower()
    if direction in ("horizontal", "横向", "h"):
        rotated = dict(p)
        rotated["w"], rotated["h"] = h, w
        rotated["direction"] = "vertical"
        inner = _measure_display_svg(rotated)
        return f'<g transform="translate({w},0) rotate(90)">{inner}</g>'

    min_value = _safe_num(p.get("min"), 0.0)
    max_value = _safe_num(p.get("max"), 100.0)
    if max_value <= min_value:
        max_value = min_value + 1.0
    value = max(min_value, min(max_value, _safe_num(p.get("value"), min_value)))
    ratio = (value - min_value) / (max_value - min_value)
    ratio = max(0.0, min(1.0, ratio))
    label = str(p.get("label", "") or "")
    position = str(p.get("position", "right")).strip().lower()
    stroke = "#333"
    text = "#333"
    parts = []

    if kind == "ruler":
        x0, body_w = 8.0, max(18.0, w - 16.0)
        parts.append(f'<rect x="{x0}" y="6" width="{body_w}" height="{max(18.0, h-18)}" rx="2" fill="#f6e6a8" stroke="{stroke}" stroke-width="1.2"/>')
        tick_count = 10
        for i in range(tick_count + 1):
            x = x0 + body_w * i / tick_count
            tick_h = 12 if i % 5 == 0 else 7
            parts.append(f'<line x1="{x}" y1="6" x2="{x}" y2="{6+tick_h}" stroke="{stroke}" stroke-width="1"/>')
            if i % 5 == 0:
                parts.append(f'<text x="{x}" y="{h-4}" font-size="9" text-anchor="middle" fill="{text}">{int(min_value+(max_value-min_value)*i/tick_count)}</text>')
        parts.append(f'<line x1="{x0+body_w*ratio}" y1="6" x2="{x0+body_w*ratio}" y2="{h-12}" stroke="#d33" stroke-width="2"/>')
    elif kind == "spring_scale":
        body_x, body_w = w * 0.28, w * 0.38
        top, bottom = 8.0, h - 16.0
        parts.append(f'<rect x="{body_x}" y="{top}" width="{body_w}" height="{bottom-top}" rx="4" fill="#f4f4f4" stroke="{stroke}" stroke-width="1.3"/>')
        parts.append(f'<path d="M {w/2} {top+10} q {-body_w/3} 7 0 14 t 0 14 t 0 14 t 0 14" fill="none" stroke="#777" stroke-width="1.1"/>')
        for i in range(11):
            y = top + 10 + (bottom-top-20) * i / 10
            x1 = body_x + body_w
            x2 = x1 + (8 if i % 5 == 0 else 5)
            parts.append(f'<line x1="{x1}" y1="{y}" x2="{x2}" y2="{y}" stroke="{stroke}" stroke-width="1"/>')
            if i % 5 == 0:
                parts.append(f'<text x="{x2+3}" y="{y+3}" font-size="8" fill="{text}">{max_value-(max_value-min_value)*i/10:g}</text>')
        pointer_y = top + 10 + (bottom-top-20) * (1-ratio)
        parts.append(f'<path d="M {body_x-9} {pointer_y} l 7 -4 v 8 z" fill="#d33"/>')
    else:
        # 量筒与温度计共用竖直刻度骨架，读数差异由液面/液柱表达。
        body_x, body_w = w * 0.30, w * 0.34
        top, bottom = 8.0, h - 18.0
        parts.append(f'<rect x="{body_x}" y="{top}" width="{body_w}" height="{bottom-top}" rx="{body_w/2}" fill="rgba(210,230,240,.18)" stroke="{stroke}" stroke-width="1.3"/>')
        if kind == "thermometer":
            parts.append(f'<circle cx="{w/2}" cy="{bottom+body_w*.42}" r="{body_w*.42}" fill="#e33" stroke="{stroke}" stroke-width="1"/>')
            liquid_top = bottom - (bottom-top) * ratio
            parts.append(f'<rect x="{w/2-body_w*.18}" y="{liquid_top}" width="{body_w*.36}" height="{bottom-liquid_top}" fill="#e33"/>')
        else:
            liquid_top = bottom - (bottom-top) * ratio
            parts.append(f'<rect x="{body_x+2}" y="{liquid_top}" width="{body_w-4}" height="{max(0.0,bottom-liquid_top)}" fill="rgba(70,150,220,.30)"/>')
            parts.append(f'<ellipse cx="{w/2}" cy="{liquid_top}" rx="{body_w/2-2}" ry="2" fill="rgba(70,150,220,.45)"/>')
        side = body_x + body_w if position not in ("left", "左") else body_x
        tick_dir = 1 if side > w/2 else -1
        for i in range(11):
            y = top + (bottom-top) * i / 10
            length = 9 if i % 5 == 0 else 5
            x2 = side + tick_dir * length
            parts.append(f'<line x1="{side}" y1="{y}" x2="{x2}" y2="{y}" stroke="#666" stroke-width="1"/>')
            if i % 5 == 0:
                tx = x2 + tick_dir * 3
                anchor = "start" if tick_dir > 0 else "end"
                val = max_value - (max_value-min_value) * i / 10
                parts.append(f'<text x="{tx}" y="{y+3}" font-size="8" text-anchor="{anchor}" fill="#666">{val:g}</text>')

    if label:
        parts.append(f'<text x="{w/2}" y="{h+11}" font-size="10" text-anchor="middle" fill="{text}">{label}</text>')
    return "\n".join(parts)


