def _spring_svg(p: dict) -> str:
    """弹簧"""
    w = p.get("w", 16)
    h = p.get("h", 55)
    label = p.get("label", "")
    segs = 8
    seg_h = h / segs
    pts = " ".join([f"{w if i%2==1 else 0},{i*seg_h}" for i in range(segs + 1)])
