# ──────────── 尺规作图原子组件（2026-07-31 新增） ────────────
# 安全约定：坐标限制 ±500，最大步数 50，数值字段 _safe_num 兜底，
# 文字字段 html.escape；steps 动作白名单 arc/line/mark/perp。

_STEP_MAX = 50
_COORD_MAX = 500.0


def _clamp_coord(v: float) -> float:
    """限制坐标在 [-_COORD_MAX, _COORD_MAX] 范围内。"""
    if not math.isfinite(v):
        return 0.0
    return max(-_COORD_MAX, min(_COORD_MAX, v))


def _safe_steps(p: dict) -> list:
    """提取并校验 steps 列表（动作白名单 + 步数上限）。"""
    raw = p.get("steps", [])
    if not isinstance(raw, list):
        return []
    out = []
    allowed = {"arc", "line", "mark", "perp"}
    for st in raw[:_STEP_MAX]:
        if not isinstance(st, dict):
            continue
        action = st.get("action", "")
        if action not in allowed:
            continue
        out.append(st)
    return out


def _compass_arc_svg(p: dict) -> str:
    """圆规弧 - 接收 steps=[{action:'arc',center:[x,y],r,start,end}]。

    无 steps 时画默认示意（1/4 圆弧 + 圆心点），保证调色板预览可见。
    """
    w = max(20, min(2000, _safe_num(p.get("w"), 80)))
    h = max(20, min(2000, _safe_num(p.get("h"), 80)))
    label = str(p.get("label", "") or "")
    parts = [f'<rect x="0" y="0" width="{w}" height="{h}" fill="none" stroke="none"/>']
    steps = _safe_steps(p)
    if steps:
        for st in steps:
            ctr = st.get("center", [0, 0])
            try:
                cx = _clamp_coord(float(ctr[0]))
                cy = _clamp_coord(float(ctr[1]))
            except (TypeError, ValueError, IndexError):
                cx, cy = 0.0, 0.0
            r = max(0.0, min(_COORD_MAX, _safe_num(st.get("r"), 10)))
            a0 = math.radians(_safe_num(st.get("start", 0), 0))
            a1 = math.radians(_safe_num(st.get("end", 90), 90))
            x0 = cx + r * math.cos(a0)
            y0 = cy + r * math.sin(a0)
            x1 = cx + r * math.cos(a1)
            y1 = cy + r * math.sin(a1)
            # SVG arc: large-arc-flag=0, sweep-flag=1
            parts.append(
                f'<path d="M{x0:.2f},{y0:.2f} A{r:.2f},{r:.2f} 0 0 1 {x1:.2f},{y1:.2f}" '
                f'fill="none" stroke="#335" stroke-width="1.5"/>'
            )
            parts.append(f'<circle cx="{cx:.2f}" cy="{cy:.2f}" r="1.5" fill="#335"/>')
    else:
        # 默认示意：1/4 圆弧
        cx, cy, r = w * 0.2, h * 0.8, min(w, h) * 0.6
        parts.append(
            f'<path d="M{cx+r:.2f},{cy:.2f} A{r:.2f},{r:.2f} 0 0 0 {cx:.2f},{cy-r:.2f}" '
            f'fill="none" stroke="#335" stroke-width="1.5"/>'
        )
        parts.append(f'<circle cx="{cx:.2f}" cy="{cy:.2f}" r="1.5" fill="#335"/>')
    if label:
        parts.append(f'<text x="{w/2}" y="{h+12}" font-size="11" fill="#333" text-anchor="middle">{label}</text>')
    return "\n".join(parts)


def _ruler_line_svg(p: dict) -> str:
    """直尺线 - 接收 steps=[{action:'line',from:[x,y],to:[x,y]}]。

    无 steps 时画默认示意（带刻度的水平直尺线）。
    """
    w = max(20, min(2000, _safe_num(p.get("w"), 80)))
    h = max(20, min(2000, _safe_num(p.get("h"), 40)))
    label = str(p.get("label", "") or "")
    parts = [f'<rect x="0" y="0" width="{w}" height="{h}" fill="none" stroke="none"/>']
    steps = _safe_steps(p)
    if steps:
        for st in steps:
            fr = st.get("from", [0, 0])
            to = st.get("to", [0, 0])
            try:
                x0 = _clamp_coord(float(fr[0])); y0 = _clamp_coord(float(fr[1]))
            except (TypeError, ValueError, IndexError):
                x0, y0 = 0.0, 0.0
            try:
                x1 = _clamp_coord(float(to[0])); y1 = _clamp_coord(float(to[1]))
            except (TypeError, ValueError, IndexError):
                x1, y1 = 0.0, 0.0
            parts.append(
                f'<line x1="{x0:.2f}" y1="{y0:.2f}" x2="{x1:.2f}" y2="{y1:.2f}" '
                f'stroke="#335" stroke-width="1.5"/>'
            )
    else:
        # 默认示意：水平直尺线 + 刻度
        y0 = h * 0.5
        parts.append(f'<line x1="4" y1="{y0:.2f}" x2="{w-4:.2f}" y2="{y0:.2f}" stroke="#335" stroke-width="1.5"/>')
        n = max(2, int(w / 10))
        for i in range(n + 1):
            tx = 4 + (w - 8) * i / n
            tl = 4 if i % 2 == 0 else 2
            parts.append(f'<line x1="{tx:.2f}" y1="{y0:.2f}" x2="{tx:.2f}" y2="{y0+tl:.2f}" stroke="#335" stroke-width="1"/>')
    if label:
        parts.append(f'<text x="{w/2}" y="{h+12}" font-size="11" fill="#333" text-anchor="middle">{label}</text>')
    return "\n".join(parts)


def _equal_length_mark_svg(p: dict) -> str:
    """等长标记 - 在两条线段端点画等长刻度标记。

    接收 steps=[{action:'mark',from:[x,y],to:[x,y]}]（每条 mark 画一条线段+端点等长记号）。
    无 steps 时画默认示意（两条带等长记号的线段）。
    """
    w = max(20, min(2000, _safe_num(p.get("w"), 80)))
    h = max(20, min(2000, _safe_num(p.get("h"), 40)))
    label = str(p.get("label", "") or "")
    parts = [f'<rect x="0" y="0" width="{w}" height="{h}" fill="none" stroke="none"/>']

    def _draw_marked(x0, y0, x1, y1, tick="//"):
        parts.append(
            f'<line x1="{x0:.2f}" y1="{y0:.2f}" x2="{x1:.2f}" y2="{y1:.2f}" '
            f'stroke="#335" stroke-width="1.5"/>'
        )
        mx, my = (x0 + x1) / 2, (y0 + y1) / 2
        parts.append(
            f'<text x="{mx:.2f}" y="{my-3:.2f}" font-size="10" fill="#e33" '
            f'text-anchor="middle">{html.escape(tick, quote=True)}</text>'
        )

    steps = _safe_steps(p)
    if steps:
        for st in steps:
            fr = st.get("from", [0, 0])
            to = st.get("to", [0, 0])
            try:
                x0 = _clamp_coord(float(fr[0])); y0 = _clamp_coord(float(fr[1]))
            except (TypeError, ValueError, IndexError):
                x0, y0 = 0.0, 0.0
            try:
                x1 = _clamp_coord(float(to[0])); y1 = _clamp_coord(float(to[1]))
            except (TypeError, ValueError, IndexError):
                x1, y1 = 0.0, 0.0
            _draw_marked(x0, y0, x1, y1, str(st.get("tick", "//")))
    else:
        # 默认示意：两条等长线段
        _draw_marked(6, h * 0.35, w * 0.45, h * 0.35, "//")
        _draw_marked(w * 0.55, h * 0.65, w - 6, h * 0.65, "//")
    if label:
        parts.append(f'<text x="{w/2}" y="{h+12}" font-size="11" fill="#333" text-anchor="middle">{label}</text>')
    return "\n".join(parts)


def _perpendicular_mark_svg(p: dict) -> str:
    """垂直标记 - 直角符号。

    接收 steps=[{action:'perp',at:[x,y],dx:...,dy:...}]（at 为角顶点，dx/dy 为两腿方向）。
    无 steps 时画默认示意（一个直角符号）。
    """
    w = max(20, min(2000, _safe_num(p.get("w"), 40)))
    h = max(20, min(2000, _safe_num(p.get("h"), 40)))
    label = str(p.get("label", "") or "")
    parts = [f'<rect x="0" y="0" width="{w}" height="{h}" fill="none" stroke="none"/>']

    def _draw_perp(vx, vy, dx, dy):
        s = 8  # 直角符号边长
        # 沿两腿方向各取 s 长度，画小方块
        import math as _m
        def _unit(a, b):
            mag = _m.sqrt(a * a + b * b)
            return (a / mag, b / mag) if mag > 0 else (0.0, 0.0)
        ux, uy = _unit(dx, dy)
        # 另一腿方向（垂直）：旋转 90 度
        px, py = -uy, ux
        p1 = (vx + ux * s, vy + uy * s)
        p2 = (vx + ux * s + px * s, vy + uy * s + py * s)
        p3 = (vx + px * s, vy + py * s)
        parts.append(
            f'<polyline points="{p1[0]:.2f},{p1[1]:.2f} {p2[0]:.2f},{p2[1]:.2f} '
            f'{p3[0]:.2f},{p3[1]:.2f}" fill="none" stroke="#335" stroke-width="1.2"/>'
        )

    steps = _safe_steps(p)
    if steps:
        for st in steps:
            at = st.get("at", [0, 0])
            try:
                vx = _clamp_coord(float(at[0])); vy = _clamp_coord(float(at[1]))
            except (TypeError, ValueError, IndexError):
                vx, vy = 0.0, 0.0
            dx = _safe_num(st.get("dx", 1), 1)
            dy = _safe_num(st.get("dy", 0), 0)
            _draw_perp(vx, vy, dx, dy)
    else:
        # 默认示意：左下角直角符号
        _draw_perp(w * 0.2, h * 0.8, 1, 0)
    if label:
        parts.append(f'<text x="{w/2}" y="{h+12}" font-size="11" fill="#333" text-anchor="middle">{label}</text>')
    return "\n".join(parts)


def _grid_paper_svg(p: dict) -> str:
    """方格背景 - rows/cols/cell 参数，整数格点。

    无 rows/cols 时按默认 cell 自适应铺满。
    """
    w = max(20, min(2000, _safe_num(p.get("w"), 100)))
    h = max(20, min(2000, _safe_num(p.get("h"), 100)))
    cell = max(4, min(50, _safe_num(p.get("cell"), 20)))
    rows = p.get("rows")
    cols = p.get("cols")
    if rows is None:
        rows = max(1, int(h / cell))
    if cols is None:
        cols = max(1, int(w / cell))
    try:
        rows = max(1, min(100, int(rows)))
        cols = max(1, min(100, int(cols)))
    except (TypeError, ValueError):
        rows, cols = max(1, int(h / cell)), max(1, int(w / cell))
    label = str(p.get("label", "") or "")
    parts = [f'<rect x="0" y="0" width="{w}" height="{h}" fill="rgba(255,255,255,0.6)" stroke="#ccc" stroke-width="1"/>']
    for i in range(1, cols):
        gx = i * (w / cols)
        parts.append(f'<line x1="{gx:.2f}" y1="0" x2="{gx:.2f}" y2="{h}" stroke="#dde" stroke-width="0.8"/>')
    for j in range(1, rows):
        gy = j * (h / rows)
        parts.append(f'<line x1="0" y1="{gy:.2f}" x2="{w}" y2="{gy:.2f}" stroke="#dde" stroke-width="0.8"/>')
    if label:
        parts.append(f'<text x="{w/2}" y="{h+12}" font-size="11" fill="#333" text-anchor="middle">{label}</text>')
    return "\n".join(parts)


