# 兼容别名
ALIASES = {
    "flask": "conical_flask",
    "bunsen_burner": "alcohol_lamp",
    "erlenmeyer": "conical_flask",
    "cylinder": "graduated_cylinder",
    "tube": "delivery_tube",
    "stand": "iron_stand",
    "clamp": "iron_stand",
    "abs_parabola": "function_curve",
}


def resolve_type(ctype: str) -> str:
    """解析组件类型（支持别名）"""
    if ctype in COMPONENT_DB:
        return ctype
    return ALIASES.get(ctype, ctype)


def get_component(ctype: str) -> dict | None:
    """获取组件定义"""
    ctype = resolve_type(ctype)
    return COMPONENT_DB.get(ctype)
